add("bullets", chapter="Từ mới (57 từ)", section="Từ mới 生词", title="Phần 1: Từ mới",
    items=["Bài 33 có 57 từ mới, chia thành 19 nhóm nhỏ",
           "Mỗi từ: nghe đọc mẫu 2 lần → âm Hán Việt → nghĩa → ví dụ",
           "Hãy đọc to theo sau mỗi lần nghe",
           "Chú ý các từ có âm đọc đặc biệt: 为期 (wéi), 闭塞 (sè), 播种 (zhǒng), 正月 (zhēng)"],
    say=["Bây giờ chúng ta sang phần một: từ mới. Bài này có năm mươi bảy từ, thầy chia thành mười chín nhóm nhỏ, mỗi nhóm ba từ.",
         F(1, "Với mỗi từ, các bạn sẽ nghe đọc mẫu hai lần, sau đó là âm Hán Việt, nghĩa, và một ví dụ."),
         F(2, "Hãy đọc to theo sau mỗi lần nghe, vì đọc thành tiếng giúp nhớ từ lâu hơn rất nhiều."),
         F(3, "Một số từ có âm đọc đặc biệt như 为期，闭塞，播种，正月, thầy sẽ nhắc khi gặp. Ngoài ra thầy cũng sẽ lưu ý những từ có âm Hán Việt quen nhưng nghĩa khác tiếng Việt. Chúng ta bắt đầu nhé.")])

for g in range(0, len(V), 3):
    group = V[g:g + 3]
    words, say = [], []
    for i, (zh, py, hv, loai, vi, ex, exvi, expl) in enumerate(group):
        n = g + i + 1
        words.append({"zh": zh, "py": py, "hv": hv.upper(), "loai": f"{n}. {loai}", "vi": vi, "ex": ex, "exvi": exvi})
        say.append(F(i, f"Từ số {n}: {zh}。 {zh}。 Hán Việt là {hv}.", zr=120))
        say.append(F(i, f"{expl} Ví dụ: {ex}{'' if ex[-1] in '。…！？' else '，'} {exvi[0].upper() + exvi[1:]}{'' if exvi.endswith(('.', '!', '?')) else '.'}", zr=130))
    add("vocab", section="Từ mới 生词", title=f"Từ mới ({g + 1}–{g + len(group)} / {len(V)})",
        words=words, say=say)

# ======================= BÀI KHÓA =======================
# (chữ Hán, bản dịch, ghi chú[, bản đọc: số viết bằng chữ Hán, bỏ ngoặc kép])
P = [
    ("为期三天的假期，我和儿时的好友结伴去西安旅行。",
     "Kỳ nghỉ kéo dài ba ngày, tôi cùng người bạn thân từ thuở nhỏ rủ nhau đi du lịch Tây An.",
     ["为期三天的假期: 为期 cộng khoảng thời gian, làm định ngữ, nghĩa là kéo dài bao lâu. 儿时 là thuở nhỏ, cách nói văn viết của 小时候.",
      "结伴 là kết bạn đồng hành, rủ nhau cùng đi. 西安 là Tây An, cố đô nổi tiếng ở vùng Tây Bắc Trung Quốc."]),
    ("去时乘高铁，车程6小时。列车缓缓离开了车站，很快就以征服一切的气势甩开窗外的景致，以300公里的时速跨过了桥梁，穿越了平原。",
     "Lúc đi, chúng tôi đi tàu cao tốc, hành trình mất 6 tiếng. Đoàn tàu chầm chậm rời ga, rồi rất nhanh đã bỏ lại cảnh vật ngoài cửa sổ với khí thế như muốn chinh phục tất cả, lao qua những cây cầu, vượt qua những cánh đồng bằng với vận tốc 300 ki-lô-mét một giờ.",
     ["高铁 là viết tắt của 高速铁路, đường sắt cao tốc. Theo chú thích của sách, đó là tuyến đường sắt chở khách chạy với tốc độ trên hai trăm ki-lô-mét một giờ. Ở Trung Quốc, tàu mang chữ G là tàu cao tốc, chữ D là tàu động lực, còn chữ T và chữ K là tàu nhanh thông thường.",
      "Cấu trúc 以……的气势 là với khí thế…, và 以……的时速 là với vận tốc…. 车程 là thời gian đi tàu xe. Tác giả dùng một loạt động từ mạnh: 甩开，跨过，穿越, để tả tốc độ của tàu cao tốc."],
     "去时乘高铁，车程六小时。列车缓缓离开了车站，很快就以征服一切的气势甩开窗外的景致，以三百公里的时速跨过了桥梁，穿越了平原。"),
    ("车窗外，模糊的景象夹杂着西北的风沙呼啸而过。坐在宽敞座椅中的人们，享受着齐全的软硬件设施，看电影的看电影，打电话的打电话，更多的则是把自己封闭在小小的手机屏幕中，不是用语言，而是用符号传递着各自的情感。",
     "Ngoài cửa sổ, cảnh vật nhòe đi, lẫn trong gió cát Tây Bắc, rít lên vụt qua. Những người ngồi trên ghế rộng rãi tận hưởng đầy đủ tiện nghi cả phần cứng lẫn phần mềm, người thì xem phim, người thì gọi điện thoại, còn phần đông thì thu mình trong màn hình điện thoại nhỏ xíu, truyền đạt tình cảm của mình không phải bằng lời nói, mà bằng những ký hiệu.",
     ["看电影的看电影，打电话的打电话: người thì xem phim, người thì gọi điện. Đây chính là điểm ngữ pháp thứ nhất của bài, dùng để liệt kê các tình huống khác nhau. 更多的则是 nghĩa là còn phần đông hơn thì….",
      "不是……而是…… nghĩa là không phải… mà là…. 西北 là vùng Tây Bắc Trung Quốc, theo chú thích của sách gồm các tỉnh như 陕西，甘肃，青海, nơi có nhiều gió cát."]),
    ("寄情于虚拟世界的网迷们对喧哗的现实流露出的是不屑一顾的冷淡。",
     "Những tín đồ mạng gửi gắm tình cảm vào thế giới ảo, đối với hiện thực ồn ào xung quanh thì chỉ để lộ ra vẻ lạnh nhạt, chẳng thèm đoái hoài.",
     ["寄情于 nghĩa là gửi gắm tình cảm vào…; 于 là giới từ văn viết, giống 在. 网迷 là người mê mạng, như 球迷 là người mê bóng đá.",
      "Cấu trúc nhấn mạnh 流露出的是…… nghĩa là cái lộ ra chính là…. Tác giả đối lập thế giới ảo với hiện thực ồn ào."]),
    ("伴随着“终点站到了”的广播，我和朋友像千千万万旅途中的人们一样，没等车停稳，就兴冲冲地守候在车门口，迫不及待地投入到西安滚滚的人流中。",
     "Cùng với tiếng loa thông báo đã đến ga cuối, tôi và bạn cũng giống như hàng nghìn hàng vạn người đang trên đường đi, tàu chưa dừng hẳn đã hớn hở đứng chờ sẵn ở cửa toa, rồi nóng lòng hòa vào dòng người cuồn cuộn của Tây An.",
     ["伴随着 nghĩa là cùng với, đi kèm với. 没等车停稳，就……: tàu chưa dừng hẳn đã…, cấu trúc 没等……就…… diễn tả sự nôn nóng.",
      "兴冲冲 là hớn hở, hăm hở. 迫不及待 là nóng lòng không đợi được. 滚滚的人流 là dòng người cuồn cuộn. Đoạn này cho thấy nhịp sống vội vã của chuyến đi."]),
    ("三天的旅行很快就结束了，我们回程坐特快，将近13个小时的硬座。列车没有了高铁的威风，不紧不慢地开出了车站，不温不火地匀速前行，仿佛知道一路上将会演绎出许许多多的故事。",
     "Ba ngày du lịch nhanh chóng kết thúc. Chuyến về, chúng tôi đi tàu nhanh, ngồi ghế cứng gần 13 tiếng. Đoàn tàu không còn vẻ oai phong của tàu cao tốc, thong thả rời ga, đều đều tiến về phía trước, như thể biết rằng dọc đường sẽ diễn ra biết bao câu chuyện.",
     ["硬座 là ghế cứng. Theo chú thích của sách, vé ngồi tàu hỏa Trung Quốc chia thành 硬座 và 软座, ghế cứng và ghế mềm; vé nằm chia thành 硬卧 và 软卧; còn tàu cao tốc có 一等座，二等座 và 商务座.",
      "Chú ý các cụm bốn chữ: 不紧不慢 là thong thả, không vội; 不温不火 là không nóng không lạnh, đều đều. Chúng đối lập với 高铁的威风 ở trên. 仿佛 nghĩa là dường như."],
     "三天的旅行很快就结束了，我们回程坐特快，将近十三个小时的硬座。列车没有了高铁的威风，不紧不慢地开出了车站，不温不火地匀速前行，仿佛知道一路上将会演绎出许许多多的故事。"),
    ("不久我就发现硬座车厢信号很差无法上网；灯光昏暗无法看书；没有电源，耗尽了电量的手机无法充电；人多嘈杂混乱得睡不着觉，闭塞的车厢里，我们像是回到了50年前。",
     "Không lâu sau, tôi phát hiện toa ghế cứng sóng rất yếu, không lên mạng được; đèn tối mờ, không đọc sách được; không có ổ điện, điện thoại cạn pin không sạc được; người đông, ồn ào hỗn loạn đến mức không ngủ được. Trong toa tàu bí bách ấy, chúng tôi như quay về 50 năm trước.",
     ["Câu này có bốn vế song song, vế nào cũng có 无法, nghĩa là không thể, không có cách nào: 无法上网，无法看书，无法充电. Cách lặp này nhấn mạnh sự bất tiện.",
      "耗尽了电量 là cạn sạch pin. 嘈杂 là ồn ào. 闭塞 ở đây là bí bách, cách biệt với thế giới bên ngoài. 回到了五十年前: như quay về năm mươi năm trước, khi chưa có điện thoại di động và mạng internet."],
     "不久我就发现硬座车厢信号很差无法上网；灯光昏暗无法看书；没有电源，耗尽了电量的手机无法充电；人多嘈杂混乱得睡不着觉，闭塞的车厢里，我们像是回到了五十年前。"),
    ("朋友忽然说：“其实有时候吧，我还挺喜欢这种感觉的，只有这时候，人和人之间才有种久违的亲近感，也许是因为我们手头都没有事情，愿意彼此分享和倾听。”之后发生的一切，都像是在证明朋友的话是对的。",
     "Bạn tôi bỗng nói: Thật ra đôi khi ấy mà, tớ lại khá thích cảm giác này, chỉ những lúc thế này, giữa người với người mới có cảm giác gần gũi đã lâu lắm rồi không có, có lẽ vì trong tay chúng ta chẳng có việc gì làm, nên sẵn lòng chia sẻ và lắng nghe nhau. Mọi chuyện xảy ra sau đó dường như đều chứng minh lời bạn tôi là đúng.",
     ["其实有时候吧: trợ từ ngữ khí ở cuối cụm này dùng để ngắt nhịp trong khẩu ngữ, giống như ấy mà. 只有……才…… nghĩa là chỉ có… mới….",
      "久违的亲近感 là cảm giác gần gũi lâu lắm mới có lại. 手头 là trong tay. 彼此 là lẫn nhau. Câu cuối chuyển ý sang những câu chuyện tiếp theo trên tàu."]),
    ("昏暗的灯光下，我和朋友开始聊天儿。她讲起小学的时候，班里颇具正义感的女生李芳芳如何见义勇为，在洪水中英勇救人；",
     "Dưới ánh đèn tối mờ, tôi và bạn bắt đầu trò chuyện. Cô ấy kể chuyện hồi tiểu học, cô bạn Lý Phương Phương trong lớp, người rất có tinh thần chính nghĩa, đã dũng cảm làm việc nghĩa, anh dũng cứu người trong trận lũ như thế nào;",
     ["颇具 nghĩa là khá có, rất có, văn viết; 颇 là khá, rất. 正义感 là tinh thần chính nghĩa. 如何 là như thế nào, cách nói văn viết của 怎么样.",
      "Câu kết thúc bằng dấu chấm phẩy, vì vế sau sẽ chuyển sang câu chuyện của chính tác giả."]),
    ("我感叹初中时，班里那个贵族气十足的男生，他叫……唉，一时竟忘了他叫什么名字。他16岁到了农村，从播种开始学习，后来长成了个精壮的汉子，改革开放后第一批承包了土地，就此发家致富，他简直就是一代人中的奇迹。",
     "Còn tôi thì cảm thán về cậu bạn thời cấp hai đầy khí chất quý tộc trong lớp, cậu ấy tên là… ôi, nhất thời lại quên mất cậu ấy tên gì. Năm 16 tuổi cậu về nông thôn, bắt đầu học từ việc gieo hạt, sau này thành một người đàn ông vạm vỡ, sau cải cách mở cửa là một trong những người đầu tiên nhận khoán đất, từ đó làm giàu, cậu ấy quả thực là một kỳ tích của cả một thế hệ.",
     ["贵族气十足 là đầy khí chất quý tộc; 十足 là mười phần, tràn đầy. 一时竟忘了: 一时 là nhất thời, bỗng chốc, đây là điểm ngữ pháp thứ hai của bài; 竟 là vậy mà, lại.",
      "改革开放 là cải cách mở cửa, bắt đầu từ cuối những năm bảy mươi thế kỷ hai mươi. 承包了土地 là nhận khoán đất. 发家致富 là làm giàu. 就此 là từ đó. Một cậu bé dáng quý tộc lại trở thành nông dân làm giàu, thật là kỳ tích!"],
     "我感叹初中时，班里那个贵族气十足的男生，他叫，唉，一时竟忘了他叫什么名字。他十六岁到了农村，从播种开始学习，后来长成了个精壮的汉子，改革开放后第一批承包了土地，就此发家致富，他简直就是一代人中的奇迹。"),
    ("我们想起小学的地理老师，讲课的时候总会带出些方言，班里调皮的男生千方百计跟她捣乱，弄得老师狼狈不堪，那会儿的我们真是幼稚得可笑。",
     "Chúng tôi nhớ đến cô giáo dạy địa lý hồi tiểu học, lúc giảng bài lúc nào cũng lẫn chút tiếng địa phương, đám con trai nghịch ngợm trong lớp tìm đủ mọi cách phá cô, làm cô khốn đốn vô cùng; hồi đó chúng tôi thật là trẻ con đến buồn cười.",
     ["带出些方言 là lẫn ra chút tiếng địa phương. 调皮 là nghịch ngợm. 千方百计 là trăm phương nghìn kế. 跟她捣乱 là phá phách cô ấy.",
      "弄得老师狼狈不堪 là làm cho cô giáo khốn đốn không chịu nổi. 那会儿 là hồi đó, khẩu ngữ. 幼稚得可笑 là trẻ con đến buồn cười."]),
    ("还有，中学我们班那个料事如神的诸葛亮……火车上，我们边回忆边开心地笑着，好像很久很久都没有这么纯粹地开心过了。",
     "Còn nữa, cậu Gia Cát Lượng đoán việc như thần của lớp cấp hai chúng tôi… Trên tàu, chúng tôi vừa hồi tưởng vừa cười vui vẻ, dường như đã rất lâu rồi không được vui một cách trọn vẹn như vậy.",
     ["料事如神 là đoán việc như thần. 诸葛亮 là Gia Cát Lượng, nhân vật thời Tam Quốc nổi tiếng mưu trí. Tác giả gọi người bạn giỏi đoán việc là 诸葛亮, đây chính là phép tu từ 借代 mà ta học ở cuối bài.",
      "边回忆边开心地笑着: cấu trúc 边……边…… là vừa… vừa…. 纯粹 là thuần túy, trọn vẹn."]),
    ("说笑累了，朋友看着窗外，我则观察着周围的人们。坐我对面的像是一对双胞胎姐弟，他们正在聊家常。",
     "Cười nói mệt rồi, bạn tôi nhìn ra ngoài cửa sổ, còn tôi thì quan sát những người xung quanh. Ngồi đối diện tôi hình như là một cặp chị em sinh đôi, họ đang trò chuyện chuyện nhà.",
     ["我则观察着: 则 ở đây nghĩa là còn… thì, dùng để đối chiếu hai người: bạn tôi nhìn ra cửa sổ, còn tôi thì quan sát mọi người. 像是 nghĩa là hình như là. 聊家常 là nói chuyện nhà."]),
    ("姐姐轻声细语，回顾着陈年往事：改革开放后的第一年，弟弟考上了大学，瞬间，这消息成了方圆百里的爆炸性新闻。",
     "Người chị nói nhỏ nhẹ, nhớ lại chuyện cũ năm xưa: năm đầu tiên sau cải cách mở cửa, cậu em thi đỗ đại học, trong nháy mắt, tin này trở thành tin chấn động khắp vùng trăm dặm.",
     ["轻声细语 là nói khẽ khàng, nhỏ nhẹ. 陈年往事 là chuyện cũ năm xưa. 瞬间 là trong nháy mắt.",
      "方圆百里 là khắp vùng trăm dặm xung quanh. 爆炸性新闻 là tin chấn động, nghĩa đen là tin có tính bùng nổ. Thời đó, đỗ đại học là chuyện rất hiếm và rất vẻ vang."]),
    ("那一年过春节弟弟在学校没回家，家里节过得别提多冷清了，对联都懒得贴。虽然弟弟写信来拜年，可全家都觉得没了天伦之乐。",
     "Năm đó, Tết cậu em ở lại trường không về nhà, cái Tết ở nhà thì khỏi phải nói vắng vẻ đến thế nào, đến câu đối cũng chẳng buồn dán. Tuy cậu em có viết thư về chúc Tết, nhưng cả nhà đều thấy mất đi niềm vui sum họp.",
     ["别提多冷清了 là khẩu ngữ, nghĩa là khỏi phải nói vắng vẻ đến mức nào. 懒得贴 là chẳng buồn dán, 懒得 là lười, không muốn làm.",
      "虽然弟弟写信来拜年，可…… là tuy cậu em viết thư chúc Tết, nhưng…. 天伦之乐 là niềm vui sum họp gia đình."]),
    ("那一年除夕、元宵节，不，是整个正月都过得没了生气，爸妈大年初一连寺庙都懒得去，天天感叹孩子翅膀硬了就要飞了，眼神中流露着失落。",
     "Năm đó, đêm giao thừa, Tết Nguyên tiêu, à không, phải nói là cả tháng Giêng đều trôi qua thiếu sức sống. Mùng một Tết, bố mẹ đến chùa cũng chẳng buồn đi, ngày nào cũng than con cái cứng cáp rồi là bay đi mất, trong ánh mắt lộ rõ vẻ hụt hẫng.",
     ["除夕 là đêm giao thừa, 大年初一 là mùng một Tết. 不，是整个正月 là cách tự sửa lời để nhấn mạnh: à không, phải nói là cả tháng Giêng. 没了生气 ở đây là thiếu sức sống, không phải là hết giận.",
      "连寺庙都懒得去 là đến chùa cũng chẳng buồn đi. 翅膀硬了 nghĩa đen là cánh đã cứng, nghĩa bóng là con cái đã lớn, tự lập, rời xa cha mẹ. 失落 là hụt hẫng."]),
    ("隔着过道坐着一对新婚的夫妇，新郎新娘一边给大家分发喜糖，一边说他们是旅行结婚的，顿时，整节车厢都热闹起来了，有人提议新郎新娘唱支歌，大家立刻鼓掌响应，",
     "Bên kia lối đi có một cặp vợ chồng mới cưới, chú rể cô dâu vừa chia kẹo cưới cho mọi người, vừa nói họ đang đi du lịch thay cho đám cưới; lập tức, cả toa tàu trở nên náo nhiệt, có người đề nghị chú rể cô dâu hát một bài, mọi người liền vỗ tay hưởng ứng,",
     ["隔着过道 là cách một lối đi. 喜糖 là kẹo cưới. 旅行结婚 là cưới bằng cách đi du lịch, thay cho việc tổ chức tiệc cưới.",
      "顿时 là lập tức, ngay lúc đó. 唱支歌 là hát một bài, 支 là lượng từ cho bài hát. Câu văn này rất dài, kéo sang cả hai đoạn sau."]),
    ("那新郎一看就是个老实人，脸憋得通红，说他是社区物业干维修的，就会干活儿，不会唱歌，不过他媳妇不光贤惠，歌也唱得好，就让媳妇代表了，",
     "anh chú rể nhìn qua là biết người thật thà, mặt đỏ bừng, nói mình làm thợ sửa chữa ở ban quản lý khu dân cư, chỉ biết làm việc, không biết hát, nhưng vợ anh không chỉ hiền thục mà còn hát hay, nên để vợ đại diện,",
     ["一看就是 là nhìn qua là biết ngay. 脸憋得通红 là mặt đỏ bừng vì ngượng. 干维修的 là làm nghề sửa chữa. 就会干活儿 là chỉ biết làm việc.",
      "不光贤惠，歌也唱得好: cấu trúc 不光……也…… là không chỉ… mà còn…. 不光 giống 不但 nhưng mang tính khẩu ngữ hơn."]),
    ("果然新娘张嘴就惊动了整节车厢，掌声、赞美声响成一片，现场简直就像联欢会一样，而我们对面角落里坐着的漫画家，早就用画笔记录下了眼前的一切。",
     "quả nhiên cô dâu vừa cất tiếng đã làm cả toa tàu xôn xao, tiếng vỗ tay, tiếng khen ngợi vang lên rần rần, khung cảnh chẳng khác gì một buổi liên hoan văn nghệ, còn họa sĩ truyện tranh ngồi ở góc đối diện chúng tôi thì đã dùng bút vẽ ghi lại tất cả cảnh tượng trước mắt từ lúc nào.",
     ["张嘴就 là vừa mở miệng đã. 惊动了整节车厢 là làm cả toa xôn xao. 响成一片 là vang lên rần rần. 现场 ở đây là khung cảnh tại chỗ, lát nữa ta sẽ phân biệt với 当场.",
      "联欢会 là buổi liên hoan văn nghệ. Sau đoạn này sách có một dòng dấu chấm lửng, nghĩa là đã lược bớt một phần câu chuyện."]),
    ("我和朋友不由得感叹，现代交通的确高效，人们随意打发着路上的时间，仓促间投入目的地的怀抱，早就忘了其实沿途的风景也是旅途的一部分，人和人之间无拘无束的交流也是人生最宝贵的财富。",
     "Tôi và bạn không khỏi cảm thán: giao thông hiện đại quả thật hiệu quả, người ta tùy ý giết thời gian trên đường, rồi vội vàng lao vào vòng tay của nơi cần đến, từ lâu đã quên rằng thật ra phong cảnh dọc đường cũng là một phần của chuyến đi, sự giao lưu thoải mái giữa người với người cũng là tài sản quý giá nhất của đời người.",
     ["不由得 là không khỏi, bất giác. 打发时间 là giết thời gian. 仓促间 là trong lúc vội vàng. 投入目的地的怀抱 là lao vào vòng tay của nơi cần đến, một cách nói nhân hóa.",
      "Đây là câu chủ đề của cả bài: 沿途的风景也是旅途的一部分, phong cảnh dọc đường cũng là một phần của chuyến đi."]),
    ("若不如此，我们又怎么会读到古人在那一束月光，一叶小舟，或者在那青山绿水间所寄托的情感呢！",
     "Nếu không như vậy, làm sao chúng ta có thể đọc được những tình cảm mà người xưa đã gửi gắm vào một dải ánh trăng, một chiếc thuyền con, hay giữa non xanh nước biếc kia!",
     ["若不如此 là nếu không như vậy, văn viết. Câu 我们又怎么会读到古人的情感呢！ là câu hỏi tu từ, nghĩa là làm sao có thể đọc được, tức là chắc chắn không thể.",
      "一束月光 là một dải ánh trăng, 一叶小舟 là một chiếc thuyền nhỏ như chiếc lá. 青山绿水 là non xanh nước biếc. Những hình ảnh này gợi đến thơ văn cổ điển, kết thúc bài bằng nỗi nhớ về cuộc sống chậm."]),
]

add("bullets", chapter="Bài khóa", section="Bài khóa 课文", title="Phần 2: Bài khóa 怀念慢生活",
    items=["Đọc từng đoạn: nghe tiếng Trung trước (chưa hiện bản dịch)",
           "Sau đó: bản dịch tiếng Việt + giải thích từ ngữ, cấu trúc",
           "Mẹo: tạm dừng, đọc to đoạn văn trước khi nghe giảng"],
    say=["Tiếp theo là phần hai: bài khóa 怀念慢生活, dài một nghìn ba trăm sáu mươi chín chữ. Bài được cải biên từ bài viết 从前慢, Ngày xưa chậm, đăng trên 北京青年报, tờ Thanh niên Bắc Kinh.",
         F(0, "Thầy chia bài thành từng đoạn ngắn. Với mỗi đoạn, các bạn nghe đọc tiếng Trung trước, cố gắng hiểu bằng các từ mới vừa học."),
         F(1, "Sau đó bản dịch tiếng Việt sẽ hiện ra, và thầy giải thích các từ ngữ, cấu trúc quan trọng."),
         F(2, "Nếu muốn luyện đọc, các bạn hãy tạm dừng và tự đọc to đoạn văn trước khi nghe giảng nhé.")])

for i, item in enumerate(P, 1):
    zh, vi, notes = item[:3]
    spoken = item[3] if len(item) > 3 else zh.replace("“", "").replace("”", "")
    zsize = 54 if len(zh) <= 100 else 50
    add("passage", section="Bài khóa 课文", title=f"Bài khóa – đoạn {i}/{len(P)}", zh=zh, vi=vi, zsize=zsize,
        say=[F(0, spoken, cap="(Nghe đọc đoạn văn tiếng Trung)", zr=150),
             F(1, "Dịch nghĩa: " + vi, cap="")] + [F(1, n) for n in notes])

add("bullets", chapter="Tóm tắt nội dung", section="Bài khóa 课文", title="Bố cục bài khóa (theo bài tập 5)", size=34,
    items=["## 1. 去时乘坐高铁的情形 – chuyến đi bằng tàu cao tốc",
           "车程6小时 · 时速300公里 · 看电影的看电影，打电话的打电话 · 寄情于虚拟世界 · 终点站",
           "## 2. 回程与去时有何不同 – chuyến về: tàu chậm gần 13 tiếng",
           "车程 · 速度 · 网络信号 · 灯光 · 电源 · 环境",
           "## 3. 我跟朋友聊了些什么 – 李芳芳 · 贵族气十足的男生 · 地理老师 · 诸葛亮",
           "## 4. 我周围的人在做什么 – 双胞胎姐弟 · 新婚小两口",
           "## 5. 我们的感受 – 沿途的风景也是旅途的一部分"],
    say=["Chúng ta cùng nhìn lại bố cục của cả bài khóa. Bài tập năm trong sách gợi ý đúng bố cục này, gồm năm phần.",
         F(0, "Phần một: 去时乘坐高铁的情形, cảnh đi tàu cao tốc lúc đi."),
         F(1, "Hành trình sáu tiếng, vận tốc ba trăm ki-lô-mét một giờ; người trên tàu thì 看电影的看电影，打电话的打电话, phần đông gửi gắm tình cảm vào thế giới ảo; đến ga cuối thì vội vã hòa vào dòng người."),
         F(2, "Phần hai: 回程与去时有何不同？ Chuyến về khác chuyến đi thế nào?"),
         F(3, "Tác giả so sánh về thời gian đi, tốc độ, sóng mạng, ánh đèn, nguồn điện và môi trường trong toa. Chuyến về chậm hơn, thiếu thốn hơn rất nhiều."),
         F(4, "Phần ba: 我跟朋友聊了些什么？ Tôi và bạn đã nói chuyện gì trên tàu? Bạn tôi kể về Lý Phương Phương dũng cảm cứu người; tôi kể về cậu bạn đầy khí chất quý tộc; cả hai cùng nhớ cô giáo địa lý và cậu Gia Cát Lượng của lớp."),
         F(5, "Phần bốn: 我周围的人在做什么？ Những người xung quanh đang làm gì? Cặp chị em sinh đôi nhớ chuyện cũ, và đôi vợ chồng mới cưới chia kẹo, hát cho cả toa nghe."),
         F(6, "Phần năm: 我们的感受, cảm nhận của chúng tôi: phong cảnh dọc đường cũng là một phần của chuyến đi, và sự giao lưu giữa người với người là tài sản quý giá nhất. Bố cục này rất có ích khi các bạn làm bài tập viết tóm tắt ở cuối bài.")])

